import { roleTitle } from './interaction-ui-v40.js';
import { rememberedContacts, getThread } from './conversations.js';
import { contactPage } from './character-voice.js';
import { renderAvatar } from './avatar.js';
const relation=n=>n>=80?'A close bond':n>=65?'Trusted':n>=40?'Familiar':n>=20?'Acquainted':'Distant';
const factLabels={shared_methods:'You shared methods for inspecting household work and making their own choices.'};
const words=m=>typeof m==='string'?m:m?.text||m?.description||'';
function readableFact(s,f){
 const key=typeof f==='string'?f:'';if(factLabels[key])return factLabels[key];
 if(!key)return words(f);
 const match=/^story_(.+)_(\d+)_(care|enterprise|coercion)$/.exec(key),arc=match&&s.stories?.arcs.find(a=>a.id===match[1]),choice=arc?.choices?.[Number(match?.[2])];
 if(choice&&choice.id===match[3])return `Chapter ${Number(match[2])+1}: ${choice.outcome||choice.label}`;
 if(key==='condition_vampire')return 'You told this person about your vampirism.';
 if(key==='condition_lycanthrope')return 'You told this person about your transformation.';
 return /^[a-z0-9_:-]+$/.test(key)?'An earlier shared experience remains recorded in your conversations.':key;
}
export const BOND_CATEGORIES=[['close','Close Contacts'],['household','Household'],['party','Party'],['recent','Recently Met'],['family','Family'],['lovers','Lovers'],['friends','Friends'],['acquaintances','Acquaintances'],['rivals','Rivals'],['enemies','Enemies'],['all','Everyone Met']];
export function bondCategory(s,p){
 if(s.age>=18&&p.age>=18&&(p.id===s.life?.partnerId||p.id===s.life?.courtshipId))return 'lovers';
 if(/enemy|hostile/i.test(p.role||'')||p.bond<=5)return 'enemies';
 if(p.familyRole||p.id===s.life?.partnerId||(s.life?.children||[]).some(c=>c.id===p.id)||(s.family?.members||[]).some(m=>m.personId===p.id)||p.role==='your child')return 'family';
 if(/rival/i.test(p.role||''))return 'rivals';
 if(p.kind==='companion'||/friend|partner/i.test(p.role||'')||p.bond>=65)return 'friends';
 return 'acquaintances';
}
export function peopleRecordPage(s,{scope='family',query='',page=0,selectedId=null,focusId=null}={}) {
 const people=rememberedContacts(s),category=scope==='circle'?'family':scope==='nearby'?'all':scope;
 const household=new Set((s.family?.members||[]).filter(m=>m.availability==='present').map(m=>m.personId)),party=new Set((s.companions||[]).filter(p=>p.recruited).map(p=>p.id));
 const filtered=people.filter(p=>category==='all'||category==='close'&&p.bond>=65||category==='household'&&household.has(p.id)||category==='party'&&party.has(p.id)||category==='recent'&&Number.isSafeInteger(s.conversations?.meetings?.[p.id]?.lastDay)&&s.day-s.conversations.meetings[p.id].lastDay<=30||bondCategory(s,p)===category||category==='family'&&p.id===s.life?.partnerId),v=contactPage(s,filtered,{scope:'all',query,page,focusId});
 return {...v,people,selected:v.contacts.find(p=>p.id===selectedId)||v.contacts[0]||null};
}
export function renderPeopleRecords(s,ui,options={}) {
 const {e,button,date,paragraphs}=ui,v=options.view||peopleRecordPage(s,options),p=v.selected;
 const scopes=BOND_CATEGORIES;
 const rows=v.contacts.map(c=>`<button type="button" class="person-record-row ${c.id===p?.id?'active':''}" data-op="contact" data-id="${e(c.id)}" aria-pressed="${c.id===p?.id}">${renderAvatar(c,{size:'small',age:c.age})}<span><strong>${e(c.name)}</strong><small>${e(roleTitle(c.role))} · ${e(relation(c.bond))}</small></span><span>${c.recordedDeath?'Deceased':c.retired?'Retired':c.available===false?'Remembered':e(c.bond)+'/100'}</span></button>`).join('');
 const list=`<aside class="people-register"><h2 id="people-results-heading" tabindex="-1">People You Have Met</h2><nav class="people-scope" aria-label="Contact scope">${scopes.map(([id,label])=>button(label,'people-scope',id,`ghost small ${options.scope===id?'active':''}`,false,(options.scope||'family')===id)).join('')}</nav><form id="people-search" class="people-search"><label class="sr-only" for="people-query">Find a remembered person</label><input id="people-query" name="query" value="${e(options.query||'')}" placeholder="Name or role"><button class="button secondary small" type="submit">Find</button>${options.query?button('Clear Search','people-clear','','ghost small'):''}</form><p class="small-copy">${options.scope==='recent'?'Recorded meetings in the last 30 days.':options.scope==='household'?'People recorded as present in your household.':options.scope==='party'?'Recruited companions, including reserves.':options.scope==='close'?'People with a recorded bond of at least 65.':'Only people already known to this life.'}</p><div class="person-register-list">${rows||'<p>No remembered person matches this view. Meet people in a settlement; opening this record creates no acquaintance.</p>'}</div><p class="small-copy" data-view-results>Showing ${v.total?v.page*12+1:0}–${Math.min(v.total,(v.page+1)*12)} of ${v.total} matching people · ${v.people.length} known overall · Page ${v.page+1} of ${v.pages}.</p><div class="contact-pagination">${button('Previous','people-page',v.page-1,'ghost small',v.page===0)}<small>${v.page+1} / ${v.pages}</small>${button('Next','people-page',v.page+1,'ghost small',v.page+1>=v.pages)}</div></aside>`;
 let record='<section class="person-memory"><h2>A place for the people who matter</h2><p>Your shared experiences, relationship and remembered words belong here. To speak with someone, find them in the world.</p>'+button('Go to Your Surroundings','place-open','','primary')+'</section>';
 if(p){
  const thread=getThread(s,p.id),meeting=s.conversations?.meetings?.[p.id],place=s.world.locations.find(l=>l.id===(meeting?.locationId||p.locationId));
  const repairs=(s.conversations?.repairs||[]).filter(r=>r.personId===p.id);
  const retirement=p.retired?`<section class="remembered-entry" data-person-retirement><h2>${p.recordedDeath?'A recorded public vacancy':'A recorded retirement'}</h2><p>${p.recordedDeath?'Public role ended after their recorded death':'Retired from'} ${e(roleTitle(p.role))}${Number.isSafeInteger(p.retiredDay)?' · '+e(date(p.retiredDay)):''}.${p.successorName?' '+e(p.successorName)+' took over the public role.':''}</p><p>${e(p.availabilityReason||'Their earlier public life remains recorded; later whereabouts are unrecorded.')} ${p.recordedDeath?'The original person and your shared history remain recorded.':'Retirement is not a report of death and does not erase your relationship.'}${p.commitmentOnly?' Your previously accepted return remains available without beginning another public service.':''}</p></section>`:'';
  const memories=(p.memories||[]).map(words).filter(Boolean),childhoodAges=memories.map(m=>/^When you were (\d+):/.exec(m)).filter(Boolean).map(m=>Number(m[1])),facts=[...(p.knownFacts||[]).map(f=>readableFact(s,f)).filter(Boolean),...(p.compatibility?.known||[]).map(k=>k.label+': '+k.value)];
  record=`<section class="person-memory" data-person-memory="${e(p.id)}"><header class="person-memory-heading">${renderAvatar(p,{size:'large',age:p.age})}<div><span class="eyebrow">A PERSON IN YOUR LIFE</span><h1>${e(p.name)}</h1><p>${e(roleTitle(p.role))} · ${p.retired?'Age '+e(p.ageAtRetirement??p.age)+(p.recordedDeath?' when their public role ended':' when they retired'):p.available===false?'Earlier acquaintance':'Age '+e(p.age)}</p><strong>${e(relation(p.bond))} · ${e(p.bond)}/100</strong></div></header><p>${e(p.description)}</p>${retirement}${p.mentorStudy?`<section class="remembered-entry" data-mentor-study><h2>Your study with this person</h2><p>${p.mentorStudy.met?'You met this mentor formally.':'No formal mentor meeting is recorded.'} ${e(p.mentorStudy.lessons)} supervised preparation lessons are recorded with this person. Earned callings and trained skills remain your own.</p></section>`:''}${p.boundary?`<p class="notice" data-person-boundary>${e(p.boundary)}</p>${button('Find Them','person-place',p.id,'secondary small')}`:''}<dl class="memory-facts"><div><dt>${meeting?'Last met':'Recorded home'}</dt><dd>${e(place?.name||'Place unrecorded')}${meeting?' · '+e(date(meeting.lastDay)):''}</dd></div><div><dt>First recorded meeting</dt><dd>${meeting?e(date(meeting.firstDay)):'An exact date was not kept in this earlier record.'}${childhoodAges.length?`<p class="small-copy">Known by age ${Math.min(...childhoodAges)}; earlier shared memories do not establish an exact first-meeting date.</p>`:''}</dd></div></dl>${p.available!==false&&place?button('Find their recorded place','person-place',p.id,'secondary'):''}<section><h2>What you share</h2>${memories.slice(-10).reverse().map(m=>`<p class="remembered-entry">${e(m)}</p>`).join('')||'<p class="muted">No specific shared memory has been recorded yet.</p>'}</section>${facts.length?`<section><h2>What they trusted you with</h2>${facts.map(f=>`<p>${e(f)}</p>`).join('')}</section>`:''}${repairs.length?`<section><h2>Promises attended</h2>${repairs.map(r=>`<p>${e(date(r.day))} · ${r.days} days · ${r.cost} gold · ${r.reviewedDay===null?'Awaiting their answer':'Acknowledged in a meeting'}. The earlier account remains.</p>`).join('')}</section>`:''}${thread.messages.length?`<details class="recorded-words" data-disclosure="remembered-words-${e(p.id)}"><summary>Words kept from earlier meetings &amp; correspondence</summary><ol>${thread.messages.slice(-12).map(m=>`<li><small>${e(date(m.day))} · ${e(m.speakerName)}</small>${paragraphs(m.text)}</li>`).join('')}</ol></details>`:''}</section>`;
 }
 return `<div class="people-records-workspace"><header class="workspace-introduction"><span class="eyebrow">THE PEOPLE YOU KNOW</span><h1>Relationships</h1><p>A record of people you have met. Conversations happen in the world, where someone is actually present.</p></header><div class="people-records-layout">${list}${record}</div></div>`;
}
